package com.mobdeve.s18.group5.bayanihanspots.manage.programs

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Add
import androidx.compose.material.icons.filled.ArrowBack
import androidx.compose.material.icons.filled.CalendarToday
import androidx.compose.material.icons.filled.Delete
import androidx.compose.material.icons.filled.Edit
import androidx.compose.material.icons.filled.LocationOn
import androidx.compose.material.icons.filled.People
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import com.mobdeve.s18.group5.bayanihanspots.data.events.Event
import com.mobdeve.s18.group5.bayanihanspots.ui.theme.PrimaryTeal

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ManageProgramsScreen(
    programs: List<Event>,
    isLoading: Boolean,
    onBack: () -> Unit,
    onAddProgram: () -> Unit,
    onEditProgram: (String) -> Unit,
    onDeleteProgram: (String) -> Unit
) {
    var programToDelete by remember { mutableStateOf<Event?>(null) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Manage Programs") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Default.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background
                ),
                windowInsets = WindowInsets(0, 0, 0, 0)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .padding(innerPadding)
                .fillMaxSize()
        ) {
            Button(
                onClick = onAddProgram,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                shape = RoundedCornerShape(8.dp),
                colors = ButtonDefaults.buttonColors(containerColor = PrimaryTeal)
            ) {
                Icon(Icons.Default.Add, contentDescription = null)
                Spacer(modifier = Modifier.width(8.dp))
                Text("Create New Program")
            }

            if (isLoading) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator(color = PrimaryTeal)
                }
            } else if (programs.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text("You haven't created any programs yet.", color = Color.Gray)
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Tap the button above to create one!", color = Color.Gray)
                    }
                }
            } else {
                LazyColumn(
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    items(programs) { program ->
                        ProgramItem(
                            program = program,
                            onEdit = { onEditProgram(program.id) },
                            onDelete = { programToDelete = program }
                        )
                    }

                    item { Spacer(modifier = Modifier.height(80.dp)) }
                }
            }
        }
    }

    // Delete confirmation dialog
    if (programToDelete != null) {
        AlertDialog(
            onDismissRequest = { programToDelete = null },
            title = { Text("Delete Program") },
            text = {
                Text("Are you sure you want to delete \"${programToDelete!!.title}\"? This action cannot be undone.")
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        onDeleteProgram(programToDelete!!.id)
                        programToDelete = null
                    }
                ) {
                    Text("Delete", color = Color.Red)
                }
            },
            dismissButton = {
                TextButton(onClick = { programToDelete = null }) {
                    Text("Cancel")
                }
            }
        )
    }
}

@Composable
fun ProgramItem(
    program: Event,
    onEdit: () -> Unit,
    onDelete: () -> Unit
) {
    Card(
        elevation = CardDefaults.cardElevation(2.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = program.title,
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.weight(1f)
                )

                // Status badge
                val statusText: String
                val statusColor: Color
                when (program.approvalStatus) {
                    "APPROVED" -> {
                        statusText = "LIVE"
                        statusColor = Color(0xFF4CAF50)
                    }
                    "REJECTED" -> {
                        statusText = "REJECTED"
                        statusColor = Color.Red
                    }
                    else -> {
                        statusText = if (program.modificationType == "EDIT") "UNDER REVIEW" else "PENDING"
                        statusColor = Color(0xFFFF9800)
                    }
                }

                Surface(
                    color = statusColor.copy(alpha = 0.1f),
                    shape = MaterialTheme.shapes.small
                ) {
                    Text(
                        text = statusText,
                        color = statusColor,
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            // Schedule
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(
                    Icons.Default.CalendarToday,
                    contentDescription = null,
                    modifier = Modifier.size(16.dp),
                    tint = Color.Gray
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = program.schedule,
                    style = MaterialTheme.typography.bodyMedium,
                    color = Color.Gray
                )
            }

            Spacer(modifier = Modifier.height(4.dp))

            // Location
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(
                    Icons.Default.LocationOn,
                    contentDescription = null,
                    modifier = Modifier.size(16.dp),
                    tint = Color.Gray
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = program.locationLabel,
                    style = MaterialTheme.typography.bodyMedium,
                    color = Color.Gray
                )
            }

            // Volunteers count
            if (program.maxVolunteers != null) {
                Spacer(modifier = Modifier.height(4.dp))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        Icons.Default.People,
                        contentDescription = null,
                        modifier = Modifier.size(16.dp),
                        tint = Color.Gray
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "${program.currentVolunteers}/${program.maxVolunteers} volunteers signed up",
                        style = MaterialTheme.typography.bodySmall,
                        color = Color.Gray
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Action buttons
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.End
            ) {
                // Only show delete for non-approved programs
                if (program.approvalStatus != "APPROVED") {
                    IconButton(onClick = onDelete) {
                        Icon(
                            Icons.Default.Delete,
                            contentDescription = "Delete",
                            tint = Color.Red
                        )
                    }
                }

                IconButton(onClick = onEdit) {
                    Icon(
                        Icons.Default.Edit,
                        contentDescription = "Edit",
                        tint = Color.Gray
                    )
                }
            }
        }
    }
}

package com.mobdeve.s18.group5.bayanihanspots.workers
import android.content.Context import android.util.Log import androidx.work.* import java.util.concurrent.TimeUnit
/** * Manager for scheduling and controlling WorkManager jobs. */ object WorkManagerHelper { private const val TAG = "WorkManagerHelper" private const val UPLOAD_SYNC_WORK = "upload_sync_work" private const val PERIODIC_SYNC_WORK = "periodic_sync_work"
/** * Schedule an immediate one-time sync when network becomes available. * Call this after creating offline content. */ fun scheduleImmediateSync(context: Context) { val constraints = Constraints.Builder() .setRequiredNetworkType(NetworkType.CONNECTED) .build()
val uploadRequest = OneTimeWorkRequestBuilder<UploadSyncWorker>() .setConstraints(constraints) .addTag("upload_sync") .build()
WorkManager.getInstance(context).enqueueUniqueWork( UPLOAD_SYNC_WORK, ExistingWorkPolicy.REPLACE, uploadRequest )
Log.d(TAG, "Scheduled immediate sync work") }
/** * Schedule periodic background sync (every 15 minutes when connected). * Call this once on app startup. */ fun schedulePeriodicSync(context: Context) { val constraints = Constraints.Builder() .setRequiredNetworkType(NetworkType.CONNECTED) .build()
val periodicRequest = PeriodicWorkRequestBuilder<UploadSyncWorker>( 15, TimeUnit.MINUTES ) .setConstraints(constraints) .addTag("periodic_sync") .build()
WorkManager.getInstance(context).enqueueUniquePeriodicWork( PERIODIC_SYNC_WORK, ExistingPeriodicWorkPolicy.KEEP, periodicRequest )
Log.d(TAG, "Scheduled periodic sync work") }
/** * Cancel all sync work. */ fun cancelAllSync(context: Context) { WorkManager.getInstance(context).cancelAllWorkByTag("upload_sync") WorkManager.getInstance(context).cancelAllWorkByTag("periodic_sync") Log.d(TAG, "Cancelled all sync work") }
/** * Get info about pending work for debugging. */ fun getWorkInfo(context: Context, tag: String): ListenableFuture<List<WorkInfo>> { return WorkManager.getInstance(context).getWorkInfosByTag(tag) } }

